If we define 
$$g_{j}=S^{-1/2}f_{j}$$
then $\left\{ g_{1},\ldots ,g_{n}\right\} $ is a \emph{Parseval frame} in $\mathbb{C}^{m},$ and in fact, if we define 
$$
T_{p}=\left[ \begin{array}{c}
               g_{1}^{\ast } \\ 
               \vdots        \\ 
               g_{n}^{\ast }
            \end{array}
\right] 
$$
then the singular value decomposition of $T_{p}$ is 
$$
T_{p}=U\left[ \begin{array}{c}
                         I_{m} \\ 
                          0
              \end{array}
\right] V^{\ast } 
$$
where $U,V$ are the same as for $T$ and $I_{m}$ is the $m\times m$ identity matrix.

It follows that every Parseval frame $\left\{ g_{1},\ldots, g_{n}\right\} $ over $\mathbb{C}^{m}$ is of the form 
$$
\left[ \begin{array}{c}
          g_{1}^{\ast } \\ 
          \vdots        \\ 
          g_{m}^{\ast } \\ 
          \vdots        \\ 
          g_{n}^{\ast }
       \end{array}
\right] =
\left[ \begin{array}{ccc}
             u_{11} & \ldots  & u_{1m} \\ 
            \vdots  & \ddots  & \vdots \\ 
             u_{m1} & \ldots  & u_{mm} \\ 
            \vdots  & \ddots  & \vdots \\ 
             u_{n1} & \ldots  & u_{nm}
        \end{array}
\right] 
\left[ \begin{array}{ccc}
            v_{11} & \ldots  & v_{1m}  \\ 
           \vdots  & \ddots  & \vdots  \\ 
            v_{m1} & \ldots  & v_{mm}
       \end{array}
\right] 
$$
where the first matrix is the first $m$ columns of $V^{\ast }.$

Let $f:X\mapsto H$ be a frame. The operator defined by
\begin{equation}
V:H\mapsto L^2(X), \quad
(V\phi)(x) = \brak{\phi, f(x)}_H
\tag{Analysis Operator}
\end{equation}
is well-defined, bounded, and has a bounded inverse. The adjoint of $V$ is given by
\begin{equation}
V^*:L^2(X)\mapsto H, \quad
V^*\alpha = \int_X \alpha(x)f(x)\,d\mu(x),
\tag{Synthesis Operator}
\end{equation}
where convergence of the integral is taken in $H$. Finally, the operator defined by
\begin{equation} S:H\mapsto H, \quad
S\phi = V^*V\phi = \int_X\brak{\phi, f(x)}_H f(x)\,d\mu(x)
\tag{Frame Operator}
\end{equation}
is positive, self-adjoint, bounded, and has a bounded inverse.

V:H\mapsto L^2(X), \quad
(V\phi)(x) = \brak{\phi, f(x)}_H
\tag{Analysis Operator}

V^*:L^2(X)\mapsto H, \quad
V^*\alpha = \int_X \alpha(x)f(x)\,d\mu(x),
\tag{Synthesis Operator}

S:H\mapsto H, \quad
S\phi = V^*V\phi = \int_X\brak{\phi, f(x)}_H f(x)\,d\mu(x)
\tag{Frame Operator}

Let $f:X\mapsto H$ be a frame. Then, there exists a frame $\tilde{f}:X\mapsto H$ such that for all $\phi\in H$,
\begin{equation}
\phi = \int_X\brak{\phi, f(x)} \tilde{f}(x)\,d\mu(x).
\tag{Reconstruction Property}
\end{equation}
Any such $\tilde{f}$ is called a \emph{dual frame} of $f$. Moreover, if $f$ is the frame operator of $f$, then the map $\tilde{f}:X\mapsto H$ defined by $\tilde{f}(x)=S^{-1}f(x)$ is a dual frame of $f$.

If $S$ is the frame operator of $f$, then $S^{-1}$ is the frame operator of the dual frame $\tilde{f}$. Consequently, $f$ is the dual frame of $\tilde{f}$, so that for all $\phi\in H$,
\begin{equation}
\phi = \int_X\brak{\phi, \tilde{f}(x)} f(x)\,d\mu(x)
= \int_X\brak{\phi, S^{-1}f(x)} f(x)\,d\mu(x).
\end{equation}

Next, we define the projection 
\begin{equation}
\rho:\operatorname{GL}(H)\mapsto \operatorname{GL}^+(H), \quad
\rho(A)=AA^*,
\end{equation}
which is important in the proof of the following lemma establishing an important relationship between $\operatorname{GL}^+(H)$ and $\operatorname{GL}(H)$.

In addition, we define the spaces
\begin{align}
F &= \{f\in J: f \mbox{ is a frame}\} \\
F_0 &= \{f\in F: f \mbox{ is Parseval}\}.
\end{align}

Define the projection
\begin{equation}
T:F\mapsto F_0, \quad
T(f) = S(f)^{-\frac{1}{2}}f.
\end{equation}

Proceeding, we fix some Parseval frame $f_{10}\in\overline{F}_0$ and define the space
\begin{equation} F_1 = \operatorname{GL}(H)f_{10}
= \{Af_{10}: A\in \operatorname{GL}(H)\}.
\end{equation}

Next, we define the map
\begin{equation}
\theta:F_1\mapsto\operatorname{GL}(H), \quad
\theta(f) = \pi_1(\zeta^{-1}(f)).
\end{equation}

The bijection $\theta$ may be lifted to the map
\begin{equation}
\theta_*:F_1\times\overline{F}_0\mapsto F, \quad
\theta_*(f_1, f_0) = \zeta(\theta(f_1), f_0).
\end{equation}

By the commuting diagram in Section 2 and the unique factorization granted by Corollary \ref{Factorization}, it is straightforward to show that $\zeta^{-1}:F\mapsto\operatorname{GL}(H)\times\overline{F}_0$ is given by
\begin{equation}
\zeta^{-1}(f) = (S(f)^{\frac{1}{2}}U(f), \sigma\circ T(f)).
\end{equation}

Let $A\in\operatorname{GL}(H)$ and $B\in\operatorname{GL}^+(H)$. For any $\phi\in H$, we have
\[ \brak{\operatorname{ad}_A(B)\phi, \phi}
= \brak{ABA^*\phi, \phi}
= \brak{BA^*\phi, A^*\phi}\geq 0, \]
where the inequality holds since $A^*\phi\in H$ and $B$ is positive. Thus, $\operatorname{ad}_A(B)$ is positive, so that $GL^+(H)$ is closed under adjugation.

In particular, we have
\begin{align*}
\ker(\rho) &= \{A\in\operatorname{GL}(H): \rho(A)=I\} \\
&= \{A\in\operatorname{GL}(H): AA^*=I\} \\
&= U(H).
\end{align*}

We have the operator norm
\[ \|A\|_J = \sup_{f\in J,f\neq 0} \frac{\|Af\|_J}{\|f\|_J}
= \sup_{f\in J,f\neq 0}\sup_{x\in X} \frac{\|Af(x)\|_H}{\|f\|_J}. \]

The frame operator of $Af$ is given by
\begin{align*}
S(Af)\phi &= \int_X\langle\phi, (Af)(x)\rangle_H(Af)(x)\,d\mu(x) \\
&= \int_X\langle\phi,A[f(x)]\rangle_HA[f(x)]\,d\mu(x) \\
&= \int_X A\langle A^*\phi, f(x)\rangle_H f(x)\,d\mu(x).
\end{align*}

Since $A$ is bounded and hence uniformly continuous, then
\begin{align*}
S(Af)\phi &= A\int_X\langle A^*\phi, f(x)\rangle_H f(x)\,d\mu(x) \\
&= AS(f)A^*\phi.
\end{align*}
Therefore, $S(Af) = \operatorname{ad}_A(S)$.

Since $A_2^{-1}$ and $A_1$ are positive and hence self-adjoint, then
\begin{align*}
A_2^{-1}A_1A_1A_2^{-1} &= I. \\
A_1^2 &= A_2^2.
\end{align*}

Let $A\in\operatorname{GL}(H)$. Then, $Af_{10}\in F_1$. By Corollary \ref{Identity}, we have
\begin{align*}
Af_{10} &= \zeta(\pi_1(\zeta^{-1}(Af_{10})), \pi_2(\zeta^{-1}(Af_{10}))) \\
&= \zeta(\theta(Af_{10})), f_{10}) \\
&= \theta(Af_{10})f_{10}.
\end{align*}

Thus, for all $\phi\in H$, we have
\begin{equation}
U(f)\phi = \int_X\brak{\phi, \sigma(f)(x)}_H f(x)\,d\mu(x).
\end{equation}
